package com.aistock.market.refresh;
import com.aistock.common.adminrefresh.AdminMarketRefreshRecords.Constraint;
import com.aistock.market.support.MarketDatabaseFixture;import com.aistock.market.ingestion.*;import com.aistock.market.quotation.*;import com.aistock.market.version.MarketVersionRepository;
import java.math.BigDecimal;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class AdminRefreshConstraintTest {
 @Test void changedHeadRevisionFailsBeforeCollectionAndHasReplayableReceipt(){var f=new AdminRefreshFixture();String v=f.seed();var calls=new AtomicInteger();var req=f.request("admin-bad",new Constraint(v,0,f.start,"admin-market-refresh-v1"));var service=f.service((op,id,a,b)->{calls.incrementAndGet();throw new AssertionError("must not collect");});var result=service.refresh(req);assertEquals("FAILED",result.state());assertEquals("ADMIN_REFRESH_CONTEXT_CHANGED",result.errorCode());assertEquals(0,calls.get());assertEquals(v,f.head());assertEquals(result,new RefreshRepository(f.jdbc).lookup(req.operationId(),f.clock));assertEquals(result,service.refresh(req));assertEquals(0,calls.get());}
 @Test void changedVersionAndCoverageStartAreRejectedWithoutDataLoss(){for(boolean wrongVersion:new boolean[]{true,false}){var f=new AdminRefreshFixture();String v=f.seed();var calls=new AtomicInteger();var c=new Constraint(wrongVersion?"00000000-0000-0000-0000-000000000001":v,1,wrongVersion?f.start:f.start.minusDays(1),"admin-market-refresh-v1");var result=f.service((op,id,a,b)->{calls.incrementAndGet();return null;}).refresh(f.request("context-mismatch",c));assertEquals("ADMIN_REFRESH_CONTEXT_CHANGED",result.errorCode());assertEquals(0,calls.get());assertEquals(v,f.head());}}
 @Test void validConstraintUsesExistingCollectorAndPublicationPath(){var f=new AdminRefreshFixture();String old=f.seed();var calls=new AtomicInteger();var result=f.service((op,id,a,b)->{calls.incrementAndGet();assertEquals(f.start,a);assertEquals(f.end,b);return new MarketCollector.Collected(op,"AVAILABLE",f.candidate(op,true),null);}).refresh(f.request("admin-good",new Constraint(old,1,f.start,"admin-market-refresh-v1")));assertEquals("AVAILABLE",result.state());assertEquals(1,calls.get());assertEquals(result.versionId(),f.head());}
 @Test void unavailableFrozenHeadIsContextFailureNotImplicitAutomaticRefresh(){var f=new AdminRefreshFixture();String v=f.seed();f.jdbc.update("update market_data_version set status='UNAVAILABLE' where version_id=?",v);var result=f.service((op,id,a,b)->{throw new AssertionError("must not collect");}).refresh(f.request("unavailable",new Constraint(v,1,f.start,"admin-market-refresh-v1")));assertEquals("ADMIN_REFRESH_CONTEXT_CHANGED",result.errorCode());assertEquals("FAILED",new RefreshRepository(f.jdbc).lookup("unavailable",f.clock).state());}
 @Test void wrongOwnerFrozenHeadIsRejectedBeforeCollection(){var f=new AdminRefreshFixture();String v=f.seed();f.jdbc.update("insert into instrument(instrument_id,ticker,display_name,demo_only)values('SH600276','SH600276','other',false)");f.jdbc.update("update market_data_version set instrument_id='SH600276' where version_id=?",v);var calls=new AtomicInteger();var result=f.service((op,id,a,b)->{calls.incrementAndGet();return null;}).refresh(f.request("wrong-owner-refresh",new Constraint(v,1,f.start,"admin-market-refresh-v1")));assertEquals("ADMIN_REFRESH_CONTEXT_CHANGED",result.errorCode());assertEquals(0,calls.get());}
 @Test void concurrentHeadChangeDuringCollectionCannotPublish(){var f=new AdminRefreshFixture();String old=f.seed();var result=f.service((op,id,a,b)->{f.jdbc.update("update instrument_data_head set revision=revision+1");return new MarketCollector.Collected(op,"AVAILABLE",f.candidate(op,true),null);}).refresh(f.request("after-collect-race",new Constraint(old,1,f.start,"admin-market-refresh-v1")));assertEquals("FAILED",result.state());assertEquals("MARKET_REVISION_CONFLICT",result.errorCode());assertEquals(old,f.head());assertEquals(1,f.jdbc.queryForObject("select count(*) from market_data_version",Integer.class));}
}
final class AdminRefreshFixture {
 final JdbcTemplate jdbc=new MarketDatabaseFixture().jdbc();final LocalDate start=LocalDate.parse("2026-10-23"),end=LocalDate.parse("2026-10-24");final Clock clock=Clock.fixed(Instant.parse("2026-10-25T12:00:00Z"),ZoneOffset.UTC);final PublicationService publisher=new PublicationService(new MarketVersionRepository(jdbc),new CandidateValidator());
 MarketCandidate candidate(String op,boolean cal){var p=new BigDecimal("10");var bars=List.of(new RawBar(start,p,p,p,p,BigDecimal.ONE,p,1,null),new RawBar(end,p,p,p,p,BigDecimal.ONE,p,1,null));return new MarketCandidate(op,"SH600030","SH600030","fixture",false,"UNKNOWN","baostock","RAW",Instant.parse("2026-10-25T04:00:00Z"),"fixture","a".repeat(64),bars,cal?List.of(new TradingDay(start,true),new TradingDay(end,true)):List.of(),null);}
 AdminRefreshFixture(){jdbc.update("update instrument set demo_only=false where instrument_id='SH600030'");jdbc.update("delete from instrument where demo_only=false");}
 String seed(){return publisher.publish(candidate("initial-context",false)).versionId();}String head(){return jdbc.queryForObject("select version_id from instrument_data_head where instrument_id='SH600030'",String.class);}RefreshRequest request(String op,Constraint c){return new RefreshRequest(op,"SH600030",end,clock.instant().plusSeconds(90),c);}RefreshService service(MarketCollector c){return new RefreshService(new RefreshRepository(jdbc),publisher,c,clock);}
}